// C-4: CRC-02 and CRC-05 validation via code inspection
// CRC-02: ACS getAllowedPatients filters by assignedAcsId
// CRC-05: tasks.write ACS cannot bypass assignedAcsId check
import { readFileSync } from 'fs';

const patientsSrc = readFileSync('./src/utils/patients.js', 'utf8');
const helpersSrc = readFileSync('./src/utils/helpers.js', 'utf8');
const tasksSrc = readFileSync('./src/routes/tasks.js', 'utf8');

// CRC-02: getAllowedPatients must have ACS branch with assignedAcsId filter
const hasGetAllowedPts = patientsSrc.includes('getAllowedPatients');
const hasAcsFilter = patientsSrc.includes('assignedAcsId') && patientsSrc.includes("role") && patientsSrc.match(/acs.*assignedAcsId|assignedAcsId.*acs/s);
const hasCanAccess = patientsSrc.includes('canAccessPatient');
const canAccessHasAcsCheck = patientsSrc.match(/canAccessPatient[\s\S]{0,500}assignedAcsId[\s\S]{0,200}write|write[\s\S]{0,200}assignedAcsId[\s\S]{0,500}canAccessPatient/);

console.log('CRC-02 getAllowedPatients present: ' + hasGetAllowedPts);
console.log('CRC-02 ACS assignedAcsId filter present: ' + !!hasAcsFilter);
console.log('CRC-02 canAccessPatient present: ' + hasCanAccess);

// CRC-05: tasks.write requires canAccessPatient check before creating task
const tasksHasCanAccess = tasksSrc.includes('canAccessPatient');
const tasksHasAcsFilter = tasksSrc.includes('assignedAcsId') || tasksHasCanAccess;
const tasksHasWrite = helpersSrc.match(/acs[\s\S]{0,200}tasks\.write|tasks\.write[\s\S]{0,200}acs/);

console.log('CRC-05 tasks.js canAccessPatient check: ' + tasksHasCanAccess);
console.log('CRC-05 helpers.js acs has tasks.write: ' + !!tasksHasWrite);

