  const snippet = acsCapBlock[0].substring(0,200).replace(/[^\x20-\x7E\n]/g,'');
  console.log('CRC-05 ACS capabilities snippet: ' + snippet);
}

const allCRC02 = hasGetAllowedPts && !!hasAcsFilter && hasCanAccess;
const allCRC05 = tasksHasCanAccess && !!tasksHasWrite;
